sketches.source:
setcpm(84/4)

// The patch: a soft triangle with a hammer-quick attack and a long, falling decay
// Copy the const line into your own sketch and call .grand() on any note pattern
const grand = (x) => x.s("triangle").timbre("soft")
  .attack(.003).decay(1.8).sustain(.06).release(1.5).envcurve("exp")
  .lpf(3400).room(.4).size(.75)

// Reference: a scale up and down, a broken chord, then block chords
right: note("<[c4 d4 e4 f4 g4 a4 b4 c5] [c5 b4 a4 g4 f4 e4 d4 c4] [c4 e4 g4 c5 e5 c5 g4 e4] [[c4,e4,g4]@2 [f4,a4,c5]@2 [g4,b4,d5]@2 [e4,g4,c5]@2]>")
  .grand().gain(.32)

// The left hand holds the roots
left: note("<c3 g2 c3 [c3@2 f2@2 g2@2 c2@2]>").grand().gain(.28)

setcpm(88/4)

// The patch: FM at ratio 2 with a gentle tremolo, the classic tine sound
const tines = (x) => x.s("sine").fm(1.1).fmh(2).trem(4).tremdepth(.25)
  .attack(.004).decay(1.2).sustain(.25).release(.8).lpf(2600).room(.35)

// Reference: Fmaj7, Em7, Dm7, Cmaj7, then a melody over them
chords: note("<[f3,a3,c4,e4] [e3,g3,b3,d4] [d3,f3,a3,c4] [c3,e3,g3,b3]>").struct("x ~ ~ [~ x] ~ ~ x ~")
  .tines().gain(.28)
melody: note("<[c5@3 a4 g4@2 e4@2] [d5@3 b4 g4@4] [a4@2 c5@2 f5@2 e5 c5] [b4@4 g4@4]>")
  .tines().gain(.24)

setcpm(96/4)

// The patch: a narrow pulse plucked short, with a wooden case resonating around it
const harpsichord = (x) => x.s("square").pw(.15)
  .attack(.002).decay(.35).sustain(0).release(.2)
  .lpf(3800).body("box").bodymix(.3).room(.3)

// Reference: a running figure in the right hand over a walking bass
right: note("<[d5 a4 f#4 a4 d5 e5 f#5 d5] [g5 e5 c#5 e5 a5 g5 f#5 e5] [f#5 d5 b4 d5 g5 f#5 e5 d5] [c#5 a4 e5 c#5 d5@4]>")
  .harpsichord().gain(.2)
left: note("<[d3 f#3 a3 f#3] [a2 c#3 e3 c#3] [b2 d3 g2 b2] [a2 a2 d3@2]>")
  .harpsichord().gain(.18)

setcpm(60/4)

// The patch: an organ-voiced saw that speaks quickly and holds while the key is down
const pipes = (x) => x.s("sawtooth").timbre("organ")
  .attack(.06).sustain(1).release(.6).lpf(2200).space("church").room(.6)

// Reference: a chorale on the manual, and the pedal a darker stop below
manual: note("<[c4,e4,g4] [a3,c4,f4] [g3,b3,d4,g4] [g3,c4,e4]>").pipes().gain(.18)
pedal: note("<c2 f2 g2 c2>").pipes().lpf(500).gain(.24)

setcpm(92/4)

// The patch: FM bars with a long ring and a motor tremolo
const vibes = (x) => x.s("sine").fm(2).fmh(4).trem(5.5).tremdepth(.35)
  .attack(.002).decay(2).sustain(0).release(1.6).room(.4)

// Reference: a pentatonic run, a broken chord, two ringing dyads and a falling line
reference: note("<[f4 g4 a4 c5 d5 f5 d5 c5] [a4 c5 e5 g5 e5 c5 a4 g4] [[f4,a4]@4 [g4,c5]@4] [f5 ~ d5 ~ c5 ~ a4 ~]>")
  .vibes().gain(.24)

setcpm(104/4)

// The patch: a short, woody FM strike over resonator tubes
const marimba = (x) => x.s("sine").fm(.6).fmh(4)
  .attack(.001).decay(.4).sustain(0).release(.3)
  .body("tube").bodymix(.25).room(.3)

// Reference: a figure across two octaves through G, C, Am and D
reference: note("<[g3 d4 b4 d4 g4 d4 b4 d4] [c4 e4 g4 e4 c5 g4 e4 c4] [a3 e4 c5 e4 a4 e4 c5 e4] [d4 f#4 a4 d5 c5 a4 f#4 d4]>")
  .marimba().gain(.3)
low: note("<g2 c3 a2 d3>").struct("x ~ ~ x ~ ~ x ~").marimba().gain(.3)

setcpm(100/4)

// The patch: small steel bars, bright inharmonic FM with a quick fade
const glock = (x) => x.s("sine").fm(3).fmh(3.5)
  .attack(.001).decay(.9).sustain(0).release(.8).room(.45)

// Reference: a simple tune in the top register
reference: note("<[e5 g5 c6 g5] [a5 g5 e5 ~] [f5 a5 d6 a5] [g5@2 ~@2] [e5 g5 c6 e6] [d6 c6 a5 f5] [g5 b5 d6 b5] [c6@3 ~]>")
  .glock().gain(.2)

setcpm(60/4)

// The patch: long tubes, FM at the bell ratio 2.76, ringing for seconds
const chimes = (x) => x.s("sine").fm(3).fmh(2.76)
  .attack(.002).decay(4.5).sustain(0).release(4).space("hall").room(.6)

// Reference: four bells, rung in a new order each bar
reference: note("<[e4 d4 c4 g3] [c4 e4 d4 g3] [c4 d4 e4 c4] [e4 c4 d4 g3]>")
  .chimes().gain(.2)

setcpm(108/4)

// The patch: close FM and a peak in the upper mids where the steel sings
const steelpan = (x) => x.s("sine").fm(1.4).fmh(2)
  .attack(.002).decay(.7).sustain(.08).release(.4)
  .peak(5).peakfreq(1600).room(.3)

// Reference: a calypso phrase; long notes are played as rolls
reference: note("<[c5 ~ e5 g5 ~ e5 c5 ~] [d5 ~ f5 a5 ~ f5 d5 ~] [e5 g5 e5 c5 d5 b4 g4 ~] [c5*8 e5*8]>")
  .steelpan().gain(.26)

setcpm(90/4)

// The patch: a plucked tine, FM with a high ratio, and a small box beneath it
const kalimba = (x) => x.s("sine").fm(.8).fmh(5.4)
  .attack(.001).decay(1).sustain(0).release(.9)
  .body("box").bodymix(.35).room(.35)

// Reference: the thumbs alternate between low and high tines
reference: note("<[g4 b4 d4 d5 g4 b4 d4 d5] [e4 g4 c4 c5 e4 g4 c4 c5] [d4 f#4 a3 a4 d4 f#4 a3 a4] [g4 b4 d5 g5 d5 b4 g4@2]>")
  .kalimba().gain(.28)

setcpm(84/4)

// The patch: a soft pluck resonating in a guitar body
const nylon = (x) => x.s("triangle").timbre("soft")
  .attack(.003).decay(.8).sustain(.05).release(.6)
  .body("guitar").bodymix(.4).lpf(2600).room(.3)

// Reference: fingerpicking through Am, Dm, E and back to Am
reference: note("<[a2 e3 a3 c4 e4 c4 a3 e3] [d3 a3 d4 f4 a4 f4 d4 a3] [e2 b2 e3 g#3 b3 g#3 e3 b2] [a2 e3 a3 c4 [a2,e3,a3,c4,e4]@4]>")
  .nylon().gain(.3)

setcpm(120/4)

// The patch: a saw pushed into a tube curve and played through a combo cabinet
const overdrive = (x) => x.s("sawtooth").curve("tube").drive(14).bias(.1)
  .attack(.003).decay(.4).sustain(.5).release(.15)
  .lpf(3200).cab("combo").room(.2)

// Reference: two bars of power chords, then a riff
reference: note("<[[e2,b2,e3]@3 [e2,b2,e3] [g2,d3,g3]@2 [a2,e3,a3]@2] [[e2,b2,e3]@3 [e2,b2,e3] [d2,a2,d3]@2 [c2,g2,c3]@2] [e3 g3 a3 b3 d4 b3 a3 g3] [e3 ~ e3 g3 a3 ~ b3@2]>")
  .overdrive().gain(.2)

setcpm(120/4)

// The patch: a bright, short pluck; the can body gives the drumhead twang
const banjo = (x) => x.s("triangle").timbre("bright")
  .attack(.001).decay(.18).sustain(0).release(.15)
  .body("can").bodymix(.35)

// Reference: a forward roll through G, C, D and G
reference: note("<[g3 b3 d4 g4 b3 d4 g4 b4] [c4 e4 g4 c5 e4 g4 c5 e5] [d4 f#4 a4 d5 f#4 a4 d5 f#5] [g4 b4 d5 g5 d5 b4 g4@2]>")
  .banjo().gain(.26)

setcpm(72/4)

// The patch: a soft pluck with a long, warm ring
const harp = (x) => x.s("triangle").timbre("soft")
  .attack(.002).decay(1.6).sustain(0).release(1.4).room(.55).size(.8)

// Reference: a glissando up and down, then rolled chords of Eb, Ab, Bb and Eb
reference: note("<[eb3 f3 g3 ab3 bb3 c4 d4 eb4 f4 g4 ab4 bb4 c5 d5 eb5 f5] [f5 eb5 d5 c5 bb4 ab4 g4 f4 eb4 d4 c4 bb3 ab3 g3 f3 eb3] [eb3 bb3 g4 eb5 ab3 eb4 c5 ab5] [bb2 f3 d4 bb4 eb3 bb3 g4 eb5]>")
  .harp().gain(.22)

setcpm(72/4)

// The patch: a bright, dry pluck over a long wooden box
const koto = (x) => x.s("triangle").timbre("bright")
  .attack(.002).decay(.6).sustain(0).release(.7)
  .body("box").bodymix(.3).room(.45)

// Reference: the hirajoshi scale up and down, then a phrase ending on the root
reference: n("<[0 1 2 3 4 5 6 7] [7 6 5 4 3 2 1 0] [2 4 3 1 2@2 0 -1] [0 ~ 4 ~ 5@2 0@2]>").scale("D:hirajoshi").transpose(12)
  .koto().gain(.28)

setcpm(72/4)

// The patch: a bright saw with a pitch kick on each pluck, gliding between notes
const sitar = (x) => x.s("sawtooth").timbre("bright").mono(1).glide(.1)
  .penv(1).pdecay(.03).vib(6).vibdepth(.12)
  .attack(.003).decay(.6).sustain(.35).release(.4).lpf(3600).room(.45)

// Reference: phrases that climb and fall back home
reference: n("<[0 1 2 3 4@2 3 2] [4 5 6 7 8@4] [7 6 5 4 3 2 1 2] [-1 1 0@6]>").scale("C:lydian").transpose(12)
  .sitar().gain(.26)

setcpm(120/4)

// The patch: a round sine with a little grit and a woody body, plucked
const upright = (x) => x.s("sine").shape(.15)
  .attack(.004).decay(.4).sustain(.3).release(.15)
  .body("box").bodymix(.2)

// Reference: a walking line through Gm7, C7, Fmaj7 and D7
reference: note("<[g1 a1 bb1 b1] [c2 e2 g2 bb2] [f1 a1 c2 e2] [d2 f#2 a2 c3]>")
  .upright().gain(.5)

setcpm(72/4)

// The patch: a bowed saw with a gentle vibrato, resonating in a violin body
const violin = (x) => x.s("sawtooth").vib(5.5).vibdepth(.12)
  .attack(.08).sustain(.75).release(.3)
  .body("violin").bodymix(.45).lpf(3600).room(.45)

// Reference: a slow harmonic minor scale, then a singing phrase
reference: note("<[a4 b4 c5 d5] [e5 f5 g#5 a5] [e5@3 d5 c5@2 b4 a4] [b4@2 c5 e5 a5@4]>")
  .violin().gain(.22)

setcpm(60/4)

// The patch: the violin body made twice as large, darker and slower to speak
const cello = (x) => x.s("sawtooth").vib(4.8).vibdepth(.1)
  .attack(.12).sustain(.8).release(.5)
  .body("violin").bodysize(2).bodymix(.45).lpf(1600).room(.45)

// Reference: an open-string arpeggio, then a falling and rising phrase
reference: note("<[c2 g2 c3 e3] [g3@3 f3 e3@2 d3 c3] [b2@2 d3@2 g3@4] [c3@6 ~@2]>")
  .cello().gain(.28)

setcpm(60/4)

// The patch: five detuned saws, slow to swell, in a wide room
const strings = (x) => x.s("sawtooth").unison(5).detune(18)
  .attack(.6).sustain(1).release(1.5).lpf(2200).room(.7).size(.9)

// Reference: Bb, Gm, Eb and F7 voiced across the section
reference: note("<[bb2,f3,d4,f4] [g2,d3,bb3,d4] [eb3,bb3,g4] [f2,c3,a3,eb4]>")
  .strings().gain(.14)

setcpm(84/4)

// The patch: a hollow sine with a soft attack and a gentle vibrato
const flute = (x) => x.s("sine").timbre("hollow").vib(5).vibdepth(.12)
  .attack(.06).sustain(.7).release(.35).room(.45)

// Reference: a scale up and down, then a lyrical phrase
reference: note("<[g4 a4 b4 c5 d5 e5 f#5 g5] [g5 f#5 e5 d5 c5 b4 a4 g4] [d5@2 e5 g5 b5@4] [a5@2 g5 e5 d5@4]>")
  .flute().gain(.26)

setcpm(80/4)

// The patch: a plain square (mostly odd harmonics, like a clarinet), softened by a filter
const clarinet = (x) => x.s("square").pw(.5).vib(4.5).vibdepth(.06)
  .attack(.05).sustain(.75).release(.25).lpf(1700).room(.4)

// Reference: the low register, then a run up into the clarion register
reference: note("<[e3@2 g3 a3 b3@4] [a3 b3 c4 d4 e4 f#4 g4 a4] [b4@3 a4 g4@2 e4@2] [d4@2 e4@6]>")
  .clarinet().gain(.22)

setcpm(72/4)

// The patch: a reedy saw through a narrow e vowel, nasal and focused
const oboe = (x) => x.s("sawtooth").timbre("reed").vowel("e").vib(5.2).vibdepth(.08)
  .attack(.04).sustain(.7).release(.25).lpf(3000).room(.45)

// Reference: a pastoral phrase
reference: note("<[d5@3 c5 a4@2 f4@2] [g4@2 a4 bb4 a4@4] [c5@3 bb4 a4@2 g4 f4] [e4@2 f4@6]>")
  .oboe().gain(.22)

setcpm(96/4)

// The patch: a reedy saw through an o vowel, gliding between notes
const sax = (x) => x.s("sawtooth").timbre("reed").vowel("o").mono(1).glide(.05)
  .vib(5).vibdepth(.15).attack(.03).sustain(.65).release(.2).lpf(2400).room(.35)

// Reference: a swung blues lick
reference: note("<[f4 ab4 bb4 b4 c5@2 bb4 ab4] [f4@4 ~@4] [bb4 db5 eb5 e5 f5@2 eb5 db5] [bb4@6 ~@2]>").swing(4)
  .sax().gain(.24)

setcpm(60/4)

// The patch: a hollow sine, slow to speak, with a wide vibrato and long glides
const shakuhachi = (x) => x.s("sine").timbre("hollow").mono(1).glide(.15)
  .vib(4.5).vibdepth(.25).attack(.3).sustain(.7).release(1.2).room(.8).size(.9)

// Reference: long breaths that bend from note to note
reference: n("<[3@3 2] [1@2 0@2] [2@3 4] [3@4] [4@2 3 2] [1@4] [0@3 1] [0@4]>").scale("D:in sen").transpose(12)
  .shakuhachi().gain(.28)

setcpm(104/4)

// The patch: a bright saw whose filter opens on every attack, like a lip buzz
const trumpet = (x) => x.s("sawtooth").timbre("bright").lpf(1400).lpenv(2).lpattack(.03).lpdecay(.2)
  .vib(5).vibdepth(.06).attack(.02).sustain(.7).release(.15).room(.4)

// Reference: a fanfare on the open notes, then a stepwise phrase
reference: note("<[g4@2 g4 c5 e5@2 c5@2] [g5@4 e5@2 c5@2] [d5 e5 f5 g5 a5@2 g5 f5] [e5@2 d5@2 c5@4]>")
  .trumpet().gain(.22)

setcpm(66/4)

// The patch: a dark saw with a slow filter swell, far back in a hall
const horn = (x) => x.s("sawtooth").lpf(800).lpenv(1).lpattack(.12)
  .attack(.1).sustain(.8).release(.6).space("hall").room(.6)

// Reference: a noble call that rises a fifth, then an octave
reference: note("<[f3@2 c4@2 f4@4] [e4@3 d4 c4@4] [bb3@2 d4@2 g4@3 f4] [f4@8]>")
  .horn().gain(.26)

setcpm(112/4)

// The patch: a low, round saw with a short filter blip on each note
const tuba = (x) => x.s("sawtooth").lpf(450).lpenv(1).lpattack(.02)
  .attack(.02).decay(.3).sustain(.5).release(.12)

// Reference: root and fifth, oom-pah, through Bb, Eb and F
reference: note("<[bb1 ~ f1 ~] [eb2 ~ bb1 ~] [f1 ~ c2 ~] [bb1 d2 f2 bb1]>")
  .tuba().gain(.45)

setcpm(90/4)

// The patch: a reedy saw through an o vowel, bending quickly between notes
const harmonica = (x) => x.s("sawtooth").timbre("reed").vowel("o").mono(1).glide(.04)
  .vib(5.5).vibdepth(.3).attack(.03).sustain(.6).release(.2).lpf(2600).room(.35)

// Reference: two call-and-answer phrases in the blues scale
reference: n("<[0 2 3 4 6@2 4 3] [2@2 0@6] [4 6 7 9 7@2 6 4] [3 2 0@6]>").scale("A:blues").transpose(12)
  .harmonica().gain(.24)

setcpm(108/3)

// One cycle is a bar of 3/4
// The patch: two reeds tuned slightly apart, the musette wobble, through an a vowel
const accordion = (x) => x.s("sawtooth").timbre("reed").unison(2).detune(16).vowel("a")
  .attack(.03).sustain(.8).release(.15).lpf(2400).room(.3)

// Reference: a waltz, the tune on the right hand and oom-pah-pah on the left
right: note("<[e5 c5 a4] [b4@2 g#4] [d5 b4 g#4] [a4@3] [c5 e5 a5] [g5@2 f5] [e5 d5 b4] [a4@3]>")
  .accordion().gain(.2)
left: note("<[a2 [c4,e4] [c4,e4]] [e2 [d4,e4] [d4,e4]] [e2 [d4,g#4] [d4,g#4]] [a2 [c4,e4] [c4,e4]] [a2 [c4,e4] [c4,e4]] [d2 [d4,f4] [d4,f4]] [e2 [d4,g#4] [b3,d4]] [a2 [c4,e4] ~]>")
  .accordion().gain(.14)

setcpm(100/4)

// The patch: a reedy, never-breathing tone through a narrow vowel
const pipes = (x) => x.s("sawtooth").timbre("reed").vowel("e")
  .attack(.02).sustain(1).release(.1).lpf(3200)

// Reference: a tune on the chanter, with a quick grace note in the first bar
chanter: note("<[a4 ~ [g5 a4] b4 c#5@2 e5@2] [d5@2 c#5 b4 a4@4] [e5 f#5 e5 c#5 b4@2 a4 b4] [c#5@2 b4@2 a4@4]>")
  .pipes().gain(.2)

// The drones: the same patch, darker, on A and E
drones: note("[a2,a3,e4]").pipes().lpf(1200).gain(.12)

setcpm(54/4)

// The patch: the choir voice, slow to breathe in and out, in a church
const ensemble = (x) => x.s("choir").attack(1).release(2.5).space("church")

// Reference: Dm, Bb, C and A, each sung on its own vowel
reference: note("<[d3,a3,f4] [bb2,f3,d4] [c3,g3,e4] [a2,e3,c#4]>").slow(2)
  .syl("<ah oh oo ah>").ensemble().gain(.34)

setcpm(66/4)

// The patch: one soprano line, gliding between notes, in a hall
const soprano = (x) => x.s("voice").voicetype("soprano").mono(1).vglide(.1)
  .attack(.1).release(.9).space("hall")

// Reference: a scale on la, then a phrase; the syllables carry the same weights as the notes
reference: note("<[c5 d5 e5 f5] [g5 a5 b5 c6] [g5@3 e5 c5@4] [d5@2 f5@2 e5@4]>")
  .syl("<[la la la la] [la la la la] [a@3 ve ma@4] [ri@2 a@2 _@4]>")
  .soprano().gain(.3)

setcpm(100/4)

// The kit: bd sd hh oh cp rim lt mt ht cr rd
// One piece per bar, then two bars of groove that use them all
reference: s("<[bd*4] [sd*4] [hh*8] [oh*4] [cp*4] [rim*8] [lt mt ht ~] [cr ~ rd rd] [bd hh sd hh, ~ ~ ~ oh] [bd [~ bd] sd [lt mt ht], hh*8, cr ~ ~ ~]>")
  .gain(.5)

setcpm(72/4)

// The patch: a low FM tone that drops slightly in pitch, ringing in a hall
const timpani = (x) => x.s("sine").fm(1.2).fmh(1.5).penv(2).pdecay(.06)
  .attack(.002).decay(1.4).sustain(0).release(1.2).space("hall").room(.5)

// Reference: tonic and dominant strokes, growing busier, then a roll
reference: note("<[c2 ~ g1 ~] [c2 ~ g1 g1] [c2 [~ c2] g1 [~ g1]] c2*16>")
  .timpani().gain(.45)

setcpm(40/4)

// The patch: inharmonic FM plus a little ring modulation, shimmering for seconds
const gong = (x) => x.s("sine").fm(1.6).fmh(1.41).ringmod(90).ringmix(.25)
  .attack(.01).decay(8).sustain(0).release(8).space("hall").room(.7)

// Reference: two strokes a fifth apart, each left to ring out
reference: note("<c2 ~ ~ ~ g1 ~ ~ ~>").gong().gain(.3)

setcpm(128/4)

// The patch: a resonant saw with a snappy filter envelope and short notes
const acid = (x) => x.s("sawtooth").lpf(500).lpq(14).lpenv(3).lpdecay(.12)
  .attack(.002).decay(.15).sustain(.3).release(.05).legato(.6)

// Reference: a line with accents off the beat; the cutoff wanders on smooth noise
reference: n("0 0 7 0 3 0 10 5 0 12 0 3 7 0 5 3").scale("A:minor").sub(12)
  .acid().lpf(perlin.range(300, 2200)).accent("~ ~ x ~ ~ ~ x ~ ~ x ~ ~ ~ ~ x ~").gain(.35)

setcpm(140/4)

// The patch: a long sine with a punchy pitch drop, a little grit and glide between notes
const boom = (x) => x.s("sine").mono(1).glide(.07).shape(.4).penv(6).pdecay(.03)
  .attack(.003).decay(1.2).sustain(.6).release(.2)

// Reference: long notes, short pickups and slides
reference: note("<[c2@6 c2 ~ eb2@4 ~ ~ g1@2] [ab1@6 ab1 ~ g1@8]>")
  .boom().gain(.55)

setcpm(128/4)

// The patch: seven detuned saws stacked into one wide, bright voice
const supersaw = (x) => x.s("sawtooth").unison(7).detune(35)
  .attack(.01).sustain(.8).release(.3).lpf(5000).room(.35)

// Reference: an anthem lead
reference: note("<[f4@3 ab4 c5@2 eb5@2] [db5@4 c5@2 ab4@2] [ab4@2 bb4 c5 eb5@2 f5@2] [g5@6 ~@2]>")
  .supersaw().gain(.18)

setcpm(60/4)

// The patch: detuned saws, slow to rise and fall, with a filter breathing over eight bars
const pad = (x) => x.s("sawtooth").unison(4).detune(25)
  .attack(2).sustain(1).release(3)
  .lpf(sine.range(500, 1600).slow(8)).room(.8).size(.95)

// Reference: Cmaj7, Am7, Fmaj7 and G with a raised eleventh, two bars each
reference: note("<[c3,g3,e4,b4] [a2,e3,c4,g4] [f2,c3,a3,e4] [g2,d3,b3,f#4]>").slow(2)
  .pad().gain(.12)

setcpm(150/4)

// The patch: a pulse wave with a quick envelope and a touch of vibrato
const chip = (x) => x.s("square").pw(.25).vib(6).vibdepth(.05)
  .attack(.001).decay(.1).sustain(.6).release(.04)

// Reference: the same patch at each classic duty cycle, a bar at a time
reference: note("<[e5 ~ c5 e5 g5 ~ e5 c5] [f5 ~ d5 f5 a5 ~ g5 f5] [e5 g5 c6 g5 e5 c5 d5 e5] [d5 ~ b4 ~ c5@4]>")
  .chip().pw("<.125 .25 .5 .25>").gain(.18)

setcpm(60/4)

// The patch: a pure sine on one line, sliding slowly between notes with a wide vibrato
const theremin = (x) => x.s("sine").mono(1).glide(.35).vib(6).vibdepth(.3)
  .attack(.3).sustain(1).release(.8).room(.6)

// Reference: wide leaps that the glide turns into swoops
reference: note("<[a4@3 e5@5] [d5@2 c5@2 b4@4] [c5@3 a4@5] [e4@8]>")
  .theremin().gain(.24)
